/* Exit Intent CSS — DPauls Brand Design System */
@import url('https://fonts.googleapis.com/css2?family=Josefin+Sans:wght@500;600;700;800&family=Roboto:wght@400;500;700&family=Roboto+Mono:wght@700&display=swap');

/* ── Modal Wrapper & Backdrop ── */
#evg-exit-intent-popup {
  position: fixed;
  inset: 0;
  z-index: 99999;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  box-sizing: border-box;
  animation: evgFadeIn 0.3s cubic-bezier(0.16, 1, 0.3, 1);
  font-family: 'Roboto', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  -webkit-font-smoothing: antialiased;
}

.evg-overlay {
  position: fixed;
  inset: 0;
  background: rgba(15, 36, 61, 0.65);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  z-index: 99998;
  cursor: pointer;
}

@keyframes evgFadeIn {
  from { opacity: 0; }
  to   { opacity: 1; }
}

@keyframes evgSlideUp {
  from {
    opacity: 0;
    transform: scale(0.92) translateY(24px);
  }
  to {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
}

/* ── Popup Card Container ── */
.evg-popup {
  display: flex;
  flex-direction: column;
  width: 100%;
  max-width: 420px;
  background: #ffffff;
  border-radius: 20px;
  overflow: hidden;
  position: relative;
  box-shadow: 0 25px 70px rgba(15, 36, 61, 0.35), 0 0 0 1px rgba(255, 255, 255, 0.6);
  animation: evgSlideUp 0.35s cubic-bezier(0.16, 1, 0.3, 1);
  z-index: 99999;
  border: 1px solid rgba(229, 233, 240, 0.8);
}

/* ── Image Panel (Left/Top) ── */
.evg-image-panel {
  width: 100%;
  height: 180px;
  flex-shrink: 0;
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  background-color: #0f243d;
  position: relative;
}

.evg-image-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(15, 36, 61, 0.1) 0%, rgba(15, 36, 61, 0.75) 100%);
  display: flex;
  align-items: flex-end;
  padding: 16px;
  box-sizing: border-box;
}

.evg-image-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: rgba(234, 84, 85, 0.92);
  color: #ffffff;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.8px;
  text-transform: uppercase;
  padding: 5px 12px;
  border-radius: 50px;
  backdrop-filter: blur(4px);
  box-shadow: 0 4px 12px rgba(234, 84, 85, 0.4);
}

/* ── Main Content Panel ── */
.evg-main-panel {
  flex: 1;
  padding: 24px 22px 22px;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  box-sizing: border-box;
  background: #ffffff;
  position: relative;
  z-index: 2;
}

/* Badge Tag */
.evg-badge-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: #e8f7f5;
  color: #199c90;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  padding: 4px 12px;
  border-radius: 50px;
  margin-bottom: 12px;
  border: 1px solid #cceee9;
}

.evg-header {
  font-family: 'Josefin Sans', sans-serif;
  font-size: 24px;
  font-weight: 800;
  color: #0f243d;
  line-height: 1.25;
  margin: 0 0 8px 0;
  letter-spacing: -0.3px;
}

.evg-subheader {
  font-family: 'Roboto', sans-serif;
  font-size: 13.5px !important;
  color: #5a6a7e;
  font-weight: 400;
  line-height: 1.45;
  margin: 0 0 18px 0;
}

/* ── Coupon Code Box ── */
.evg-code-box {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  background: #f0fdfa;
  border: 2px dashed #199c90;
  border-radius: 12px;
  padding: 10px 16px;
  margin-bottom: 10px;
  width: 100%;
  box-sizing: border-box;
  transition: all 0.2s ease;
}

.evg-code-box:hover {
  background: #e6faf7;
  border-color: #128277;
}

.evg-code-content {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  text-align: left;
}

.evg-code-label {
  font-size: 9.5px;
  font-weight: 800;
  color: #199c90;
  letter-spacing: 1px;
  text-transform: uppercase;
}

.evg-code-text {
  font-size: 20px;
  font-weight: 800;
  letter-spacing: 2px;
  color: #0f766e;
  font-family: 'Roboto Mono', monospace;
  line-height: 1.2;
}

/* Copy Button */
.evg-copy-btn {
  background: linear-gradient(135deg, #199c90 0%, #128277 100%);
  color: #ffffff;
  border: none;
  border-radius: 8px;
  padding: 8px 16px;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  font-family: 'Roboto', sans-serif;
  letter-spacing: 0.5px;
  white-space: nowrap;
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  display: inline-flex;
  align-items: center;
  gap: 6px;
  box-shadow: 0 2px 8px rgba(25, 156, 144, 0.3);
  outline: none;
}

.evg-copy-btn:hover {
  background: linear-gradient(135deg, #128277 0%, #0a4f49 100%);
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(25, 156, 144, 0.4);
}

.evg-copy-btn.copied {
  background: linear-gradient(135deg, #10b981 0%, #059669 100%);
  box-shadow: 0 2px 8px rgba(16, 185, 129, 0.4);
}

.evg-coupon-note {
  font-size: 11.5px;
  color: #8c9ba5;
  margin: 0 0 16px 0;
  line-height: 1.4;
}

/* ── Primary CTA Button ── */
.evg-cta {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  padding: 13px 20px;
  background: linear-gradient(135deg, #199c90 0%, #128277 100%);
  color: #ffffff;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 1px;
  text-transform: uppercase;
  text-align: center;
  border: none;
  border-radius: 50px;
  cursor: pointer;
  font-family: 'Josefin Sans', 'Roboto', sans-serif;
  box-shadow: 0 6px 20px rgba(25, 156, 144, 0.35);
  transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
  margin-bottom: 12px;
  box-sizing: border-box;
  outline: none;
}

.evg-cta:hover {
  background: linear-gradient(135deg, #128277 0%, #0a4f49 100%);
  transform: translateY(-2px);
  box-shadow: 0 8px 25px rgba(25, 156, 144, 0.5);
}

.evg-cta:active {
  transform: translateY(0);
}

/* ── Dismissal Link (No thanks button) ── */
.evg-dismiss-text {
  display: inline-block;
  width: 100%;
  text-align: center;
  font-size: 12.5px;
  color: #7f8c8d;
  cursor: pointer;
  background: transparent;
  border: none;
  font-family: 'Roboto', sans-serif;
  font-weight: 500;
  padding: 6px 12px;
  transition: color 0.2s ease;
  text-decoration: none;
  outline: none;
  position: relative;
  z-index: 10;
}

.evg-dismiss-text:hover {
  color: #0f243d;
  text-decoration: underline;
}

/* ── Dismissal Circle Cross Button (Top-Right) ── */
.evg-btn-dismissal {
  position: absolute;
  top: 12px;
  right: 12px;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: #ffffff;
  border: 1px solid #e2e8f0;
  font-size: 22px;
  font-weight: 400;
  line-height: 1;
  color: #5a6a7e;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  z-index: 1000;
  padding: 0;
  outline: none;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.12);
  user-select: none;
}

.evg-btn-dismissal:hover {
  background: #ea5455;
  color: #ffffff;
  border-color: #ea5455;
  transform: rotate(90deg) scale(1.08);
  box-shadow: 0 4px 14px rgba(234, 84, 85, 0.4);
}

/* ══ TABLET & DESKTOP (Side-by-Side Layout) ══ */
@media (min-width: 680px) {
  #evg-exit-intent-popup { padding: 24px; }

  .evg-popup {
    flex-direction: row;
    width: 680px;
    max-width: 90vw !important;
    min-height: 380px;
  }

  .evg-image-panel {
    width: 44%;
    height: auto;
    min-height: 100%;
  }

  .evg-main-panel {
    width: 56%;
    padding: 32px 30px 28px;
    align-items: flex-start;
    text-align: left;
  }

  .evg-badge-tag {
    margin-bottom: 14px;
  }
  .evg-header {
    font-size: 26px;
    margin-bottom: 8px;
  }
  .evg-subheader {
    font-size: 14px !important;
    margin-bottom: 20px;
  }

  .evg-code-box {
    margin-bottom: 12px;
  }

  .evg-cta {
    width: 100%;
    padding: 14px 24px;
    font-size: 13.5px;
    margin-bottom: 12px;
  }

  .evg-dismiss-text {
    text-align: center;
    width: 100%;
  }

  .evg-btn-dismissal {
    top: 14px;
    right: 14px;
    width: 34px;
    height: 34px;
  }
}

